"""Zero-dependency offline dashboard, filterable by status/priority/region."""
import json,sqlite3,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
con=sqlite3.connect(ROOT/'data/orderflow.db');con.row_factory=sqlite3.Row
rows=[dict(r) for r in con.execute('''SELECT order_id,customer_name,region,product_name,substr(order_date,1,7) month,order_amount,status,priority,block_reason,delivered_qty,otif_flag,invoice_variance FROM v_order_360 ORDER BY order_date DESC''')]
reasons=[dict(r) for r in con.execute("SELECT block_reason reason,COUNT(*) count FROM orders WHERE status='Blocked' GROUP BY block_reason ORDER BY count DESC")]
con.close()
payload=json.dumps({'orders':rows,'reasons':reasons},separators=(',',':')).replace('</','<\\/')
page='''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OrderFlow | Operations Control Center</title>
<style>:root{--navy:#102b43;--ink:#153148;--muted:#677c8b;--teal:#087f87;--pale:#eff6f7;--line:#deeaed}*{box-sizing:border-box}body{margin:0;background:#f4f7fb;color:var(--ink);font:15px system-ui,-apple-system,Segoe UI,sans-serif}header{background:var(--navy);color:white;padding:22px max(20px,calc((100% - 1260px)/2));display:flex;justify-content:space-between;align-items:center;gap:20px}header strong{font-size:25px;letter-spacing:-.7px}.sub{font-size:12px;opacity:.8}main{max-width:1300px;margin:auto;padding:28px 20px 60px}.intro{display:flex;justify-content:space-between;gap:15px;align-items:center}.intro h1{margin:0;font-size:27px}.intro p{color:var(--muted);margin:8px 0 22px}.tag{display:inline-block;padding:8px 11px;border-radius:20px;background:#e7f4f0;color:#136450;font-weight:700;font-size:12px}.filters{display:flex;gap:14px;flex-wrap:wrap;background:white;padding:17px;border:1px solid var(--line);border-radius:14px;margin-bottom:20px}.filters label{font-weight:600;font-size:12px;color:var(--muted)}select,input{display:block;margin-top:5px;border:1px solid #cedde5;border-radius:7px;padding:9px;min-width:150px;background:white;color:var(--ink)}.cards{display:grid;grid-template-columns:repeat(5,1fr);gap:15px}.card,.panel{background:white;border:1px solid var(--line);border-radius:14px;box-shadow:0 4px 18px #142c4308}.card{padding:18px}.card .label{font-size:12px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.4px}.card .value{font-size:29px;font-weight:750;margin-top:8px;letter-spacing:-1px}.card small{color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:19px}.panel{padding:20px;min-width:0}.panel h2{font-size:17px;margin:0 0 16px}.barrow{display:grid;grid-template-columns:130px 1fr 58px;align-items:center;gap:9px;margin:12px 0;font-size:12px}.barback{background:#e8f0f2;height:15px;border-radius:7px;overflow:hidden}.bar{height:100%;background:#0d8993;border-radius:7px}.bar.orange{background:#e7a54a}.bar.red{background:#cc6870}.tablewrap{overflow:auto;max-height:505px}table{border-collapse:collapse;width:100%;font-size:12px}th{text-align:left;background:#eff4f7;padding:11px;position:sticky;top:0;white-space:nowrap}td{padding:10px;border-bottom:1px solid var(--line);white-space:nowrap}.pill{padding:3px 8px;border-radius:12px;background:#e7eef9;color:#315582;font-weight:700}.pill.blocked{background:#ffe3e2;color:#a03443}.pill.delivered{background:#e3f4e8;color:#287347}.foot{margin-top:20px;font-size:12px;color:var(--muted)}@media(max-width:980px){.cards{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}@media(max-width:550px){header{flex-direction:column;align-items:flex-start}.cards{grid-template-columns:1fr 1fr}.barrow{grid-template-columns:90px 1fr 48px}.intro{display:block}}</style></head><body>
<header><div><strong>◫ ORDERFLOW</strong><div class="sub">Customer Solutions & Order-to-Cash Analytics</div></div><div class="sub">PORTFOLIO DEMO  ·  SYNTHETIC DATA</div></header>
<main><div class="intro"><div><h1>Operations Control Center</h1><p>Order visibility, on-time-in-full performance, blocked-order exceptions and billing risk</p></div><span class="tag">100% local · no login needed</span></div>
<section class="filters"><label>Order status<select id="status"><option value="">All statuses</option><option>Blocked</option><option>Open</option><option>Delivered</option><option>Cancelled</option></select></label><label>Priority<select id="priority"><option value="">All priorities</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select></label><label>Region<select id="region"><option value="">All regions</option><option>East</option><option>Central</option><option>West</option></select></label><label>Customer / order search<input id="search" placeholder="Search order or customer"></label><label>Visible table rows<select id="limit"><option value="50">50</option><option value="150">150</option><option value="500">500</option></select></label></section>
<section class="cards"><div class="card"><div class="label">Orders matched</div><div class="value" id="total">—</div><small>Across filter selection</small></div><div class="card"><div class="label">Blocked orders</div><div class="value" id="blocked">—</div><small>Require exception review</small></div><div class="card"><div class="label">Open orders</div><div class="value" id="open">—</div><small>Not yet delivered</small></div><div class="card"><div class="label">OTIF rate</div><div class="value" id="otif">—</div><small>Delivered-only denominator</small></div><div class="card"><div class="label">Order value</div><div class="value" id="value">—</div><small>Order amount, not collections</small></div></section>
<div class="grid"><section class="panel"><h2>Order status distribution</h2><div id="statusChart"></div></section><section class="panel"><h2>OTIF by customer region</h2><div id="regionChart"></div></section></div>
<div class="grid"><section class="panel"><h2>Blocked order root causes</h2><div id="reasonChart"></div></section><section class="panel"><h2>Monthly order value</h2><div id="monthChart"></div></section></div>
<section class="panel" style="margin-top:19px"><h2>Order exception explorer <span id="rowcount" style="font-size:12px;color:#677c8b;font-weight:400"></span></h2><div class="tablewrap"><table><thead><tr><th>Sales order</th><th>Customer</th><th>Region</th><th>Status</th><th>Priority</th><th>Block reason</th><th>Order value</th><th>OTIF</th><th>Invoice variance</th></tr></thead><tbody id="table"></tbody></table></div></section><p class="foot">All accounts, customers, invoices and transactions are fictitious. OTIF = deliveries reaching customers on/before promised date, with delivered quantity ≥ ordered quantity, divided by all delivered orders. This HTML is read-only; the Streamlit application includes case status actions with an audit log.</p></main>
<script>const data=__DATA__;const $=id=>document.getElementById(id),money=n=>'$'+Math.round(n).toLocaleString(),esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
function bars(id,entries,total,cl=''){const max=Math.max(1,...entries.map(x=>x[1]));$(id).innerHTML=entries.length?entries.map(([name,v])=>`<div class="barrow"><span title="${esc(name)}">${esc(name)}</span><div class="barback"><div class="bar ${cl}" style="width:${100*v/max}%"></div></div><b style="text-align:right">${v.toLocaleString(undefined,{maximumFractionDigits:1})}${total?'%':''}</b></div>`).join(''):'<p>No records in selection</p>'}
function update(){let q=$('search').value.toLowerCase();let rows=data.orders.filter(r=>(!$('status').value||r.status==$('status').value)&&(!$('priority').value||r.priority==$('priority').value)&&(!$('region').value||r.region==$('region').value)&&(!q||r.order_id.toLowerCase().includes(q)||r.customer_name.toLowerCase().includes(q)));
const delivered=rows.filter(r=>r.status==='Delivered');$('total').textContent=rows.length.toLocaleString();$('blocked').textContent=rows.filter(r=>r.status==='Blocked').length.toLocaleString();$('open').textContent=rows.filter(r=>r.status==='Open').length.toLocaleString();$('otif').textContent=delivered.length?(100*delivered.filter(r=>r.otif_flag===1).length/delivered.length).toFixed(1)+'%':'N/A';$('value').textContent='$'+(rows.reduce((a,r)=>a+r.order_amount,0)/1000000).toFixed(2)+'M';
const count=(set,key)=>Object.entries(set.reduce((o,r)=>(o[r[key]]=(o[r[key]]||0)+1,o),{})).sort((a,b)=>b[1]-a[1]);bars('statusChart',count(rows,'status'));const grouped={};for(const r of delivered){const d=grouped[r.region]||(grouped[r.region]=[0,0]);d[1]++;d[0]+=r.otif_flag||0}bars('regionChart',Object.entries(grouped).map(([k,[n,d]])=>[k,+(100*n/d).toFixed(1)]),true,'orange');bars('reasonChart',count(rows.filter(r=>r.status==='Blocked'),'block_reason').slice(0,6),'','red');let months={};for(const r of rows)months[r.month]=(months[r.month]||0)+r.order_amount;bars('monthChart',Object.entries(months).sort().map(([m,v])=>[m,+(v/1e6).toFixed(2)]));
const shown=rows.slice(0,+$('limit').value);$('rowcount').textContent=`(${Math.min(rows.length,shown.length)} shown / ${rows.length} matching)`;$('table').innerHTML=shown.map(r=>`<tr><td>${esc(r.order_id)}</td><td>${esc(r.customer_name)}</td><td>${esc(r.region)}</td><td><span class="pill ${esc(r.status.toLowerCase())}">${esc(r.status)}</span></td><td>${esc(r.priority)}</td><td>${esc(r.block_reason||'—')}</td><td>${money(r.order_amount)}</td><td>${r.otif_flag===null?'—':r.otif_flag?'✓':'✕'}</td><td>${r.invoice_variance===null?'—':money(r.invoice_variance)}</td></tr>`).join('')}
for(const id of ['status','priority','region','search','limit'])$(id).addEventListener(id==='search'?'input':'change',update);update()</script></body></html>'''
(ROOT/'dashboard/OrderFlow_Offline_Dashboard.html').write_text(page.replace('__DATA__',payload),encoding='utf-8')
print('Created dashboard', (ROOT/'dashboard/OrderFlow_Offline_Dashboard.html').stat().st_size)
